INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','easy','flashcard','What are the classic symptoms of gastro-oesophageal reflux disease (GORD)?','["Burning retrosternal pain (heartburn) worsening when lying down or bending forward, relieved by antacids; may also cause regurgitation of acid or food, waterbrash, chronic cough, and hoarseness. Symptoms worsen after large meals, fatty foods, caffeine, alcohol, and smoking."]','A','GORD occurs when stomach acid refluxes into the oesophagus due to impaired lower oesophageal sphincter function. It is the most common upper GI condition. Diagnosis is clinical in typical cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','easy','flashcard','List the alarm (red flag) symptoms in a patient with dyspepsia that mandate urgent endoscopy.','["Dysphagia (especially progressive), unintentional significant weight loss, persistent vomiting, iron-deficiency anaemia, palpable epigastric mass, new-onset dyspepsia in a patient >55 years, and haematemesis."]','A','These alarm features raise concern for underlying upper GI malignancy (oesophageal or gastric cancer) and require urgent (two-week wait) referral for upper GI endoscopy. Their absence allows for empirical management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','medium','flashcard','What is the gold standard investigation for confirming GORD when the clinical diagnosis is uncertain?','["24-hour ambulatory oesophageal pH monitoring — it directly measures the time the oesophagus is exposed to acid (pH <4) and correlates symptoms with reflux episodes (DeMeester score)."]','A','24-hr pH monitoring is more specific than endoscopy for GORD, as endoscopy can be normal in many GORD patients (non-erosive reflux disease). It is indicated when symptoms are atypical, before surgery, or when empirical PPI therapy has failed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','medium','flashcard','According to the Ghana STG, what is the first-line pharmacological treatment for GORD?','["Omeprazole 20 mg once daily for 4-8 weeks, combined with lifestyle modifications (elevate head of bed, avoid fatty foods, caffeine, alcohol, smoking; avoid eating within 3 hours of bedtime; lose weight if overweight)."]','A','PPIs (proton pump inhibitors) are superior to H2-receptor antagonists (e.g., ranitidine) for symptom relief and mucosal healing in GORD. The Ghana STG recommends omeprazole as the first-line PPI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','hard','flashcard','What is Barrett''''s oesophagus and what is its clinical significance?','["Barrett''''s oesophagus is the replacement of normal stratified squamous oesophageal epithelium with specialised intestinal metaplasia (columnar epithelium with goblet cells) in the lower oesophagus, as a consequence of chronic GORD. Its key clinical significance is a 30-125-fold increased risk of oesophageal adenocarcinoma."]','A','Barrett''''s oesophagus is diagnosed on endoscopy with biopsy. Management: continue PPI, enrolment in surveillance programme (endoscopy every 3-5 years for non-dysplastic Barrett''''s). High-grade dysplasia is treated by endoscopic eradication therapy (radiofrequency ablation or endoscopic mucosal resection).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','medium','flashcard','What is the step-down approach to GORD management?','["Start with the highest level of therapy needed to control symptoms (PPI), then step down to the lowest effective therapy: PPI daily → PPI on-demand → H2-receptor antagonist → antacids as needed. Alternatively, step-up: antacids → H2RA → PPI."]','A','Step-down therapy is preferred after initial PPI-induced symptom control, to minimise long-term PPI use and associated risks (C. diff, hypomagnesaemia, bone fractures with long-term use).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','easy','flashcard','Name three key lifestyle modifications that reduce GORD symptoms.','["(1) Elevate head of bed 15-20 cm; (2) Avoid triggers: fatty foods, caffeine, chocolate, alcohol, mint, smoking; (3) Eat smaller meals and avoid eating within 3 hours of bedtime. Also: lose weight if BMI >25, avoid tight-fitting clothing."]','A','Lifestyle modifications are first-line therapy and should accompany all pharmacological treatments. Weight loss of even 5% can significantly reduce GORD symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','hard','flashcard','What complications can arise from long-standing untreated GORD?','["(1) Oesophagitis and erosive oesophagitis; (2) Peptic oesophageal stricture (fibrosis causing progressive dysphagia); (3) Barrett''''s oesophagus (intestinal metaplasia — pre-malignant); (4) Oesophageal adenocarcinoma (the most serious complication); (5) Anaemia from chronic oesophageal haemorrhage."]','A','The risk of progression from GORD to Barrett''''s oesophagus is approximately 10-15% over a lifetime. Barrett''''s to adenocarcinoma risk is ~0.5% per year. Surveillance endoscopy is key in Barrett''''s oesophagus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','medium','flashcard','What type of hiatus hernia is most commonly associated with GORD, and how does it contribute to reflux?','["Sliding hiatus hernia (type I) — the gastro-oesophageal junction (GOJ) slides above the diaphragm. This disrupts the normal anti-reflux mechanisms (lower oesophageal sphincter, phrenico-oesophageal ligament, angle of His), predisposing to acid reflux. Present in >95% of hiatus hernias."]','A','Para-oesophageal (rolling) hernias account for <5% and the GOJ remains below the diaphragm; they are more likely to cause obstruction/strangulation than reflux. Mixed hernias have features of both.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Dyspepsia & GORD','hard','flashcard','When is surgical treatment (fundoplication) indicated for GORD?','["Surgical intervention (laparoscopic Nissen fundoplication) is indicated for: (1) PPI-refractory GORD with confirmed acid/non-acid reflux on testing; (2) Patient preference to avoid long-term medication; (3) Complications not responding to medical therapy (e.g., stricture); (4) Proven GORD in young patients with good surgical fitness. Pre-operative work-up requires oesophageal manometry and 24-hr pH monitoring to confirm GORD and exclude motility disorders."]','A','Fundoplication involves wrapping the gastric fundus around the lower oesophagus to create a mechanical anti-reflux barrier. Success rates are ~85-90% for properly selected patients. Risks include dysphagia, gas bloat syndrome, and inability to belch.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','easy','flashcard','What is the most common cause of peptic ulcer disease in the world?','["Helicobacter pylori (H. pylori) infection accounts for approximately 70-90% of duodenal ulcers and 60-80% of gastric ulcers. The second most common cause is NSAID use. Zollinger-Ellison syndrome (gastrin-secreting tumour) is a rare cause of multiple, refractory peptic ulcers."]','A','H. pylori is a gram-negative microaerophilic bacterium that colonises the gastric mucosa. It causes chronic active gastritis, impairs mucosal defences, and increases acid secretion, predisposing to ulceration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','medium','flashcard','What is the best non-invasive test for active H. pylori infection, and when should it NOT be used for test of cure?','["Best non-invasive test: 13C-urea breath test (UBT) — high sensitivity (88-95%) and specificity (95-100%) for active H. pylori. Also: stool antigen test. Should NOT use for test of cure if PPIs not stopped for at least 2 weeks before testing (causes false-negative results). Serology (IgG) CANNOT be used for test of cure."]','A','The UBT works by detecting H. pylori urease activity: 13C-labelled urea is administered, H. pylori urease cleaves it to 13CO2, which is detected in exhaled breath. The test should be performed ≥4 weeks after completing eradication therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','easy','flashcard','What are the classic clinical features that distinguish duodenal ulcer from gastric ulcer?','["Duodenal ulcer: epigastric pain worse when HUNGRY/before meals, relieved by eating (food neutralises acid); pain at night; very rarely malignant. Gastric ulcer: epigastric pain worse AFTER eating (food stimulates acid secretion); can be associated with weight loss; ~1-3% risk of malignancy (all gastric ulcers need biopsy)."]','A','Duodenal ulcers are more common (4:1 over gastric ulcers). Both are associated with H. pylori and NSAID use. Gastric ulcers always need biopsies (at least 6-8 samples from ulcer edge) to exclude malignancy, and repeat endoscopy after treatment to confirm healing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','medium','flashcard','A perforated peptic ulcer is suspected. What is the first-line diagnostic investigation?','["Erect chest X-ray (or erect abdominal X-ray if chest X-ray cannot be performed): demonstrates free gas (air) under the diaphragm (pneumoperitoneum) in ~70% of perforations. If CXR is equivocal or negative and perforation is still suspected, proceed to CT abdomen with contrast (most sensitive: ~98%)."]','A','Perforated peptic ulcer presents with sudden onset severe epigastric pain radiating to the back, board-like abdominal rigidity (peritonism), absent bowel sounds, and haemodynamic instability. It is a surgical emergency requiring urgent laparotomy (or laparoscopy) for repair.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','hard','flashcard','Name the three main complications of peptic ulcer disease and their hallmark features.','["(1) Haemorrhage — haematemesis (bright red or coffee-ground), melaena; from gastroduodenal artery erosion in posterior wall; (2) Perforation — sudden severe epigastric pain, board-like rigidity, free air under diaphragm on erect CXR; (3) Gastric outlet obstruction (pyloric stenosis) — projectile non-bilious vomiting of large volumes of food, succussion splash, visible peristalsis, metabolic alkalosis."]','A','Bleeding is the most common complication (10-20% of peptic ulcers). Perforation is the most acutely life-threatening. Pyloric stenosis causes metabolic alkalosis with hypokalaemia and hypochloraemia from loss of gastric H+ and Cl-.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','medium','flashcard','What is the standard first-line H. pylori eradication regimen and its expected success rate?','["Standard triple therapy for 7-14 days: PPI (e.g., omeprazole 20 mg BD) + clarithromycin 500 mg BD + amoxicillin 1 g BD. Expected eradication rate: 80-90% in areas with low clarithromycin resistance. If clarithromycin resistance is high or first-line fails, use quadruple therapy: PPI + bismuth + metronidazole + tetracycline."]','A','Test of cure is always required ≥4 weeks after completing eradication: use 13C-UBT or stool antigen test (not serology). PPIs must be stopped 2 weeks before testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','easy','flashcard','Why should all gastric ulcers undergo repeat endoscopy after treatment?','["Gastric ulcers carry a risk of malignancy (approximately 1-3%). Repeat endoscopy at 6-8 weeks after completion of treatment is essential to: (1) confirm complete healing of the ulcer (non-healing raises concern for malignancy or ongoing NSAID use); (2) obtain further biopsies if any residual area appears abnormal."]','A','Duodenal ulcers do NOT routinely require repeat endoscopy (very rarely malignant). Gastric ulcers require multiple biopsies from the ulcer edge and base at initial endoscopy, and follow-up endoscopy to confirm healing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','hard','flashcard','What is Zollinger-Ellison syndrome and how does it present?','["Zollinger-Ellison syndrome (ZES) is caused by a gastrin-secreting tumour (gastrinoma — usually in the pancreas or duodenum, 25% associated with MEN1). Causes: massively elevated gastric acid secretion. Presents with: multiple, large, refractory peptic ulcers (often in unusual locations — distal duodenum, jejunum), severe reflux oesophagitis, and secretory diarrhoea (from acid inactivating pancreatic enzymes)."]','A','Diagnosis: fasting serum gastrin >10x ULN with gastric pH <2. Secretin stimulation test: paradoxical rise in gastrin. Management: high-dose PPI; localise and resect the tumour; octreotide for metastatic disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','medium','flashcard','When is H. pylori testing indicated in a patient presenting with uncomplicated dyspepsia without alarm features, and what is the management approach?','["H. pylori testing is indicated in all patients presenting with dyspepsia (without alarm features) aged <55 years. Recommended strategy: ''''Test and Treat'''' — non-invasive H. pylori test (urea breath test or stool antigen), eradicate if positive, and reassess. This reduces the need for empirical PPI therapy and endoscopy in young patients with functional dyspepsia."]','A','The test and treat strategy is cost-effective and endorsed by NICE and BSG guidelines. If H. pylori is negative and symptoms persist, a trial of PPI therapy is appropriate. Endoscopy is reserved for patients with alarm features or those >55 years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Peptic Ulcer Disease','hard','flashcard','A patient on long-term NSAID therapy needs gastroprotection. What strategy reduces NSAID-induced peptic ulcer risk?','["(1) Use the lowest effective NSAID dose for the shortest duration; (2) Co-prescribe a PPI (e.g., omeprazole 20 mg daily) with all regular NSAIDs in patients at risk (age >65, previous peptic ulcer, concurrent corticosteroid/anticoagulant use); (3) Consider switching to a COX-2 selective inhibitor (lower GI risk than non-selective NSAIDs); (4) Test and treat H. pylori before starting long-term NSAID therapy."]','A','NSAIDs cause peptic ulcers by inhibiting COX-1-mediated prostaglandin synthesis, which normally maintains gastric mucosal defences (mucus, bicarbonate secretion, blood flow). PPI co-prescription reduces ulcer risk by ~75% in high-risk patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','easy','flashcard','What are the two main categories of acute gastrointestinal bleeding and their characteristic presentations?','["Upper GI bleeding (proximal to ligament of Treitz): haematemesis (fresh blood or coffee-ground vomit), melaena (black, tarry, offensive stools). Lower GI bleeding (distal to ligament of Treitz): haematochezia (fresh red blood per rectum). Massive upper GI bleeding can cause haematochezia with haemodynamic instability."]','A','The most common causes of UGIB: peptic ulcer disease (35-50%), varices (10-20%), Mallory-Weiss tear (5-10%). The most common causes of LGIB: diverticular disease, haemorrhoids, angiodysplasia, colorectal cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','medium','flashcard','What are the components of the pre-endoscopy Rockall score for upper GI bleeding?','["Age: <60 years = 0; 60-79 years = 1; ≥80 years = 2. Shock: no shock (SBP >100, pulse <100) = 0; tachycardia (SBP >100, pulse >100) = 1; hypotension (SBP <100) = 2. Comorbidity: none = 0; cardiac failure, IHD, major comorbidity = 2; renal failure, liver failure, metastatic cancer = 3. Maximum pre-endoscopy score = 7 (maximum total post-endoscopy = 11). Score 0 = very low risk (<0.2% mortality)."]','A','The post-endoscopy Rockall score adds: endoscopic diagnosis (Mallory-Weiss/no lesion = 0; peptic ulcer/oesophagitis = 1; GI malignancy = 2) and stigmata of recent haemorrhage (none/dark spot = 0; blood in upper GI tract/active bleeding vessel/adherent clot = 2). Score ≥5 = high risk of re-bleeding and mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','easy','flashcard','What is the recommended haemoglobin transfusion threshold in acute non-variceal upper GI bleeding in a haemodynamically stable patient without cardiac disease?','["Transfuse packed red cells when Hb <7 g/dL, targeting a Hb of 7-9 g/dL (restrictive transfusion strategy). In patients with acute coronary syndrome or significant cardiovascular disease, use a higher threshold of Hb <8 g/dL."]','A','The TRIGGER trial and NICE guidelines (2012) support a restrictive transfusion strategy in upper GI bleeding. Over-transfusion in variceal bleeding is particularly harmful as it increases portal pressure and re-bleeding risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','medium','flashcard','A patient with cirrhosis presents with acute haematemesis. What is the initial medical treatment while arranging urgent endoscopy?','["(1) Terlipressin 2 mg IV every 4 hours (reduces splanchnic blood flow and portal pressure) — continue for up to 5 days; (2) Prophylactic IV antibiotics (ceftriaxone 1 g/day or ciprofloxacin 400 mg BD IV for 5-7 days) — reduces infection risk and improves survival; (3) Endoscopic band ligation is the definitive endoscopic treatment within 12 hours of presentation."]','A','Somatostatin and its analogues (octreotide, vapreotide) are alternatives to terlipressin where unavailable. Antibiotics (prophylaxis) in cirrhotic variceal bleeding are a Grade A recommendation, improving survival and reducing bacterial infections and re-bleeding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','hard','flashcard','What is the management of a Mallory-Weiss tear?','["Mallory-Weiss tear (linear mucosal laceration at the GOJ from forceful vomiting) — Management: (1) Most (90%) stop bleeding spontaneously with supportive care (IV fluids, PPI, antiemetics, nil by mouth); (2) Blood transfusion if Hb <7 g/dL; (3) Endoscopic haemostasis if active bleeding on endoscopy (adrenaline injection ± thermal therapy ± haemoclip); (4) Angiographic embolisation or surgery for refractory bleeding (rare)."]','A','Predisposing factors: alcohol excess, forceful vomiting in any cause (including pregnancy, bulimia, alcohol binge). Most tears are <2 cm at the GOJ or cardia. Boerhaave syndrome is a full-thickness rupture (surgical emergency), caused by the same mechanism but much rarer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','medium','flashcard','What are the indications for TIPS (transjugular intrahepatic portosystemic shunt) in variceal bleeding?','["(1) Salvage therapy for acute variceal haemorrhage not controlled by endoscopic band ligation + vasoactive drugs (failure of standard therapy); (2) Prevention of re-bleeding (secondary prophylaxis) after failure of combination therapy (beta-blockers + EVL); (3) Early TIPS (within 72 hours) for high-risk patients (Child-Pugh C score 10-13, or Child-Pugh B with active bleeding at endoscopy)."]','A','TIPS involves inserting a stent between the portal vein and hepatic vein within the liver under radiological guidance, creating a portosystemic shunt. It is effective in >90% of cases for controlling bleeding. Main complications: hepatic encephalopathy (20-30%), shunt stenosis/occlusion, hepatic decompensation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','easy','flashcard','What is the most common cause of upper GI bleeding and what is its management?','["Peptic ulcer disease (PUD) is the most common cause of upper GI bleeding (35-50%). Management: (1) Resuscitation (large-bore IV access, IV fluids, cross-match blood); (2) IV omeprazole 80 mg bolus then 8 mg/hr infusion (reduces re-bleeding in high-risk ulcers); (3) Upper GI endoscopy within 24 hours (immediate if haemodynamically unstable) — dual endoscopic therapy for high-risk stigmata; (4) Treat H. pylori if positive; (5) Stop NSAIDs and aspirin if possible."]','A','High-risk endoscopic stigmata requiring endoscopic haemostasis: active arterial spurting, visible non-bleeding vessel, adherent clot. Low-risk lesions (flat spots, clean ulcer base) can be managed conservatively without endoscopic intervention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','hard','flashcard','What is Dieulafoy''''s lesion and how does it present?','["Dieulafoy''''s lesion is an abnormally large (1-3 mm) submucosal artery that protrudes through a small mucosal defect, typically in the gastric fundus (within 6 cm of the GOJ), without surrounding ulceration. Presents as: recurrent, massive, apparently spontaneous haematemesis with no obvious mucosal lesion. It is notoriously difficult to diagnose on endoscopy."]','A','Management: endoscopic haemostasis (adrenaline injection + thermal coagulation or haemoclip). High rate of re-bleeding — may need repeat endoscopy, interventional radiology (coil embolisation), or surgical oversewing. It accounts for approximately 2% of massive upper GI bleeding.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','medium','flashcard','What is the role of high-dose IV proton pump inhibitor therapy in non-variceal upper GI bleeding?','["High-dose IV PPI (omeprazole 80 mg IV bolus then 8 mg/hr infusion for 72 hours) is recommended after successful endoscopic haemostasis of high-risk peptic ulcer lesions (active bleeding, visible vessel, adherent clot). It raises gastric pH >6, stabilising the platelet plug and blood clot, reducing re-bleeding risk. Reduces need for surgery and improves outcomes."]','A','Evidence from randomised controlled trials shows that high-dose IV PPI after endoscopic haemostasis reduces re-bleeding from ~25% to ~5% for high-risk lesions. After 72 hours, switch to oral PPI. Low-dose IV or oral PPI is sufficient for lower-risk lesions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute GI Bleeding','hard','flashcard','What are the criteria for urgent endoscopy (within 12 hours) vs routine endoscopy (within 24 hours) in acute upper GI bleeding?','["Urgent endoscopy WITHIN 12 HOURS: haemodynamic instability despite resuscitation (SBP <100 mmHg, HR >100 after 2L crystalloid), ongoing active haematemesis with haemodynamic compromise, suspected variceal haemorrhage (cirrhosis, known varices), suspected aorto-enteric fistula. WITHIN 24 HOURS: all other stable patients with acute UGIB after adequate resuscitation."]','A','Timing of endoscopy: evidence does not support endoscopy within <6 hours improving mortality in stable patients. The priority is always adequate resuscitation first. Endoscopy should only proceed once the patient is haemodynamically stable enough to tolerate the procedure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','easy','flashcard','What are the key clinical differences between Crohn''''s disease and ulcerative colitis?','["UC: continuous mucosal inflammation from rectum extending proximally; only affects colon; bloody diarrhoea, tenesmus, urgency; no granulomas; associated pANCA. Crohn''''s: transmural inflammation; skip lesions; affects any part of GI tract (mouth to anus); may have perianal disease, fistulae, strictures; granulomas; associated ASCA."]','A','Other differences: UC rarely causes small bowel involvement (backwash ileitis); UC is curative with colectomy. Crohn''''s involves the full thickness of the bowel wall — leading to fistulae, abscesses, and strictures not seen in UC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','medium','flashcard','What is the role of faecal calprotectin in IBD?','["Faecal calprotectin is a sensitive marker of intestinal inflammation (released by neutrophils migrating into the gut wall). Uses: (1) Distinguish IBD from IBS (high calprotectin favours IBD; normal calprotectin in IBS); (2) Monitor disease activity and treatment response in IBD; (3) Predict mucosal healing. Normal: <50 µg/g; borderline: 50-200 µg/g; elevated (suggests active inflammation): >200 µg/g."]','A','Faecal calprotectin is NOT diagnostic — it is elevated in any intestinal inflammation (IBD, infection, NSAID enteropathy, colorectal cancer). Colonoscopy with biopsy is required for definitive diagnosis. Calprotectin can help triage which patients need colonoscopy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','medium','flashcard','What is the induction therapy for moderate-to-severe Crohn''''s disease flare?','["Oral prednisolone 40 mg/day, tapered by 5 mg/week over 8 weeks (total course ~8-12 weeks). For severe disease or steroid-refractory disease: IV hydrocortisone 100 mg QDS in hospital; if no response in 3 days, consider anti-TNF therapy (infliximab 5 mg/kg IV). Budesonide (9 mg/day) is an alternative for mild-moderate ileocaecal Crohn''''s."]','A','Key principle: corticosteroids are for induction only, NOT maintenance (high side-effect profile with long-term use). Always co-prescribe bone protection (calcium + vitamin D, bisphosphonate if long-term steroids) and thromboprophylaxis (LMWH) in hospitalised patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','easy','flashcard','What is toxic megacolon and what are the criteria for diagnosis?','["Toxic megacolon is acute non-obstructive colonic dilatation (transverse colon diameter ≥6 cm on plain abdominal X-ray) combined with systemic toxicity. Criteria for systemic toxicity (Jalan criteria): 3 of 4: fever >38°C, HR >120 bpm, WBC >10.5 × 10⁹/L, or anaemia; PLUS one of: dehydration, altered consciousness, electrolyte disturbance, or hypotension."]','A','Toxic megacolon most commonly complicates severe UC but can occur in Crohn''''s colitis or infectious colitis (C. diff, CMV). Management: IV steroids, IV fluids, antibiotics, bowel rest, avoid antidiarrhoeals/opioids. Emergency colectomy if no improvement within 24-72 hours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','hard','flashcard','What are the indications for surgical intervention in IBD?','["UC indications: (1) Toxic megacolon/colonic perforation (emergency); (2) Severe haemorrhage; (3) Failure of medical therapy (refractory disease); (4) Dysplasia or colorectal cancer. Elective UC surgery: panproctocolectomy + ileal pouch-anal anastomosis (IPAA or ''''J-pouch'''') is the standard procedure — curative. Crohn''''s indications: (1) Intestinal obstruction from stricture; (2) Abscess/fistula not responding to medical therapy; (3) Failure of medical therapy; (4) Perianal disease; (5) Cancer."]','A','Surgery in Crohn''''s disease is NOT curative: disease recurs in approximately 30% at 1 year and 60-70% at 5 years after resection, usually at the anastomosis. Conservative resection (minimal bowel loss) is the surgical principle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','medium','flashcard','What is the role of 5-aminosalicylic acid (5-ASA/mesalazine) in IBD?','["UC: 5-ASA is used for induction of remission in mild-moderate UC and for maintenance of remission. Topical 5-ASA (suppositories for proctitis, enemas for left-sided disease) is more effective than systemic for distal disease. Also used for long-term cancer surveillance protection. Crohn''''s disease: 5-ASA is NOT effective for induction or maintenance of remission in Crohn''''s disease; it is not recommended."]','A','5-ASA acts locally in the bowel mucosa to inhibit prostaglandin and cytokine production, reducing inflammation. Side effects: headache, nausea, diarrhoea, rarely interstitial nephritis (monitor renal function annually).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','easy','flashcard','How do anti-TNF biologics (infliximab, adalimumab) work in IBD and when are they indicated?','["Anti-TNF agents (infliximab — IV; adalimumab — SC) are monoclonal antibodies that block tumour necrosis factor-alpha (TNF-α), a key pro-inflammatory cytokine in IBD. Indications: moderate-severe Crohn''''s disease or UC that is steroid-refractory (fails IV steroids) or steroid-dependent (relapse on steroid tapering) despite immunomodulators (azathioprine). Also for fistulating Crohn''''s disease."]','A','Screening before starting anti-TNF: TB (Mantoux/IGRA and CXR — anti-TNF can reactivate latent TB), hepatitis B serology, varicella/MMR immunity. Contraindications: active infection, active TB, demyelinating disease, moderate-severe heart failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','hard','flashcard','What is the Montreal classification for ulcerative colitis?','["Montreal classification classifies UC by extent: E1 (Proctitis) — confined to rectum (distal to rectosigmoid junction); E2 (Left-sided/distal) — extends to sigmoid/descending colon but not beyond splenic flexure; E3 (Extensive/pancolitis) — extends proximal to splenic flexure, including pancolitis. Severity is also classified: S0 (remission), S1 (mild: ≤4 stools/day, no systemic features), S2 (moderate: 4-6 stools/day, minimal systemic features), S3 (severe: ≥6 bloody stools/day, at least one systemic feature — Truelove and Witts criteria)."]','A','Extent of UC guides therapy: distal disease (E1-E2) — topical mesalazine preferred; extensive disease (E3) — systemic therapy required. Pancolitis carries the highest risk of colorectal cancer and requires surveillance colonoscopy every 1-2 years after 8 years of disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','medium','flashcard','What are the haematological monitoring requirements for azathioprine in IBD?','["Before starting: check TPMT (thiopurine methyltransferase) enzyme activity — patients with low/absent TPMT are at high risk of severe myelosuppression. During therapy: FBC and LFTs monthly for the first 3 months, then every 3 months. Azathioprine should be stopped if WBC <3.0 × 10⁹/L or neutrophils <1.5 × 10⁹/L. Target therapeutic range for 6-TGN (thioguanine nucleotide) metabolite: 235-450 pmol/8 × 10⁸ RBC."]','A','Main side effects of azathioprine: leucopenia/myelosuppression (dose-dependent, related to TPMT activity), hepatotoxicity, pancreatitis (occurs in ~4% in first few weeks — not dose-related), increased risk of infections and lymphoma with long-term use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','IBD - Clinical Management','hard','flashcard','When should colorectal cancer surveillance colonoscopy be performed in patients with IBD?','["Start surveillance after 8-10 years of disease (from symptom onset, not diagnosis) in: (1) Pancolitis (UC extending proximal to hepatic flexure); (2) Left-sided colitis; (3) IBD with primary sclerosing cholangitis (PSC) — annual surveillance from time of PSC diagnosis. Surveillance intervals: low risk — every 5 years; intermediate risk — every 3 years; high risk (extensive active inflammation, stricture, previous dysplasia) — annual colonoscopy."]','A','The risk of colorectal cancer in UC increases with: duration of disease (>8 years), extent of disease (pancolitis > left-sided > proctitis), severity of inflammation, co-existing PSC, family history of CRC, and age at diagnosis. Chromoendoscopy (dye-spraying) is recommended for surveillance to improve dysplasia detection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','easy','flashcard','What are the WHO criteria for defining acute diarrhoea?','["Acute diarrhoea: passage of 3 or more loose or watery stools per day (or more frequent than normal for the individual), lasting less than 14 days. Persistent diarrhoea: 14-29 days. Chronic diarrhoea: ≥30 days. Dysentery (bloody diarrhoea): diarrhoea with visible blood and/or mucus in the stools."]','A','Acute diarrhoea is the second most common cause of death in children worldwide (after respiratory tract infections). In low-income countries, dehydration from diarrhoea kills approximately 1.7 million children per year.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','medium','flashcard','What are the components of WHO low-osmolarity oral rehydration solution (ORS) recommended by the Ghana STG?','["WHO low-osmolarity ORS composition: Sodium 75 mmol/L, Chloride 65 mmol/L, Glucose (anhydrous) 75 mmol/L, Potassium 20 mmol/L, Trisodium citrate (dihydrate) 10 mmol/L. Total osmolarity: 245 mOsm/L. Available as sachets dissolved in 1 litre of clean water."]','A','This replaced the original WHO ORS (sodium 90, osmolarity 311 mOsm/L) as the low-osmolarity formula reduces stool output by ~20%, duration of diarrhoea by ~20%, and vomiting by ~30%. It also reduces the need for unscheduled IV fluids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','easy','flashcard','When are antibiotics indicated in acute diarrhoeal illness? Give examples of conditions requiring antibiotic treatment.','["Indications for antibiotics in acute diarrhoea: (1) Dysentery (bloody diarrhoea) — empirical ciprofloxacin pending culture; (2) Suspected Shigella — ciprofloxacin (adults) or azithromycin (children); (3) Cholera (Vibrio cholerae) — doxycycline (adults), azithromycin (children/pregnant); (4) Typhoid fever (Salmonella typhi) — ciprofloxacin or ceftriaxone; (5) C. difficile — oral vancomycin; (6) Giardiasis — metronidazole; (7) Severe disease in immunocompromised patients."]','A','Antibiotics are NOT indicated for: viral gastroenteritis (e.g., rotavirus), uncomplicated non-typhi Salmonella (prolongs carrier state), most ETEC traveller''''s diarrhoea (self-limiting). Inappropriate antibiotic use in diarrhoea promotes antimicrobial resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','medium','flashcard','Describe the clinical features and management of cholera.','["Clinical features: Vibrio cholerae infection. Profuse, odourless, rice-water diarrhoea (painless, caused by cholera toxin activating adenylyl cyclase → massive Cl- secretion); severe dehydration (loss of up to 1 litre/hour); vomiting; ''''washerwoman hands'''' (due to dehydration); no fever (unlike other bacterial diarrhoeas). Management: (1) Aggressive rehydration — ORS for mild-moderate dehydration; IV Ringer''''s lactate for severe dehydration; (2) Antibiotics: doxycycline 300 mg single dose (adults), azithromycin (children and pregnant women)."]','A','Cholera is caused by V. cholerae O1 and O139 serogroups. It is endemic in sub-Saharan Africa, South Asia, and areas with poor sanitation. The cholera toxin (CT) irreversibly activates adenylyl cyclase in intestinal epithelial cells, causing massive Cl- and water secretion. Oral cholera vaccines (Dukoral) are available for travellers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','hard','flashcard','What are the clinical features of typhoid fever and how does it differ from non-typhi Salmonella gastroenteritis?','["Typhoid fever (Salmonella typhi/paratyphi): (1) Incubation 7-14 days; (2) Step-wise (gradually rising) fever over 1-2 weeks; (3) Relative bradycardia (pulse disproportionately low for degree of fever — Faget sign); (4) Rose spots (salmon-coloured macules on trunk — 30% of patients); (5) Splenomegaly and hepatomegaly; (6) Constipation in first week, diarrhoea later; (7) Headache, malaise. Non-typhi Salmonella (NTS) gastroenteritis: incubation 6-72 hours, self-limiting (2-5 days), watery or bloody diarrhoea, vomiting, fever — ANTIBIOTICS NOT RECOMMENDED in healthy individuals (prolongs carrier state)."]','A','Diagnosis of typhoid: blood culture (gold standard, positive in 40-80% in first week); stool culture; Widal test (limited sensitivity/specificity). Treatment: ciprofloxacin (where sensitive) or ceftriaxone IV for severe disease; azithromycin for uncomplicated typhoid due to fluoroquinolone resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','medium','flashcard','How is dehydration assessed and classified in a child with acute diarrhoea according to WHO/Ghana STG guidelines?','["No dehydration: alert, drinks normally, eyes normal, skin pinch returns immediately; some (mild-moderate) dehydration: restless/irritable, thirsty/drinks eagerly, sunken eyes, skin pinch returns slowly (<2 seconds); severe dehydration: lethargic or unconscious, unable to drink, very sunken eyes, skin pinch returns very slowly (>2 seconds). Management: No dehydration — continue feeds, ORS after each stool; Some — ORS 75 mL/kg over 4 hours; Severe — IV Ringer''''s lactate (first 30 mL/kg over 30 min in infants, 1 hour in children), then reassess."]','A','The most reliable signs of dehydration in children: skin turgor (skin pinch test), sunken fontanelle in infants, dry mucous membranes, and decreased urine output. Weight loss is the most accurate measure of fluid deficit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','easy','flashcard','What is the most common cause of acute gastroenteritis in children in sub-Saharan Africa?','["Rotavirus is the leading cause of severe acute gastroenteritis and diarrhoeal death in children <5 years worldwide, including sub-Saharan Africa. It causes watery (non-bloody) diarrhoea, vomiting, and fever, lasting 3-8 days. Treatment is supportive (ORS). Rotavirus vaccines (Rotarix, RotaTeq) are highly effective and have been incorporated into the Ghana EPI schedule."]','A','Other important causes of childhood gastroenteritis in Ghana: E. coli (ETEC, EPEC), Shigella (causing bloody diarrhoea), Vibrio cholerae (epidemic cholera), Cryptosporidium, and adenovirus. Bacterial causes are more likely to cause bloody diarrhoea and systemic features.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','hard','flashcard','What is Clostridioides difficile infection (CDI) and who is at risk?','["Clostridioides (formerly Clostridium) difficile is a gram-positive, spore-forming, anaerobic bacillus that causes antibiotic-associated diarrhoea and colitis. It produces toxins A (enterotoxin) and B (cytotoxin). Spectrum: mild diarrhoea → pseudomembranous colitis → toxic megacolon (life-threatening). Risk factors: antibiotic use (especially clindamycin, cephalosporins, fluoroquinolones, ampicillin), hospitalisation, age >65, PPI use, immunosuppression."]','A','Diagnosis: stool PCR for C. diff toxin genes (most sensitive) or glutamate dehydrogenase (GDH) + toxin EIA (two-step algorithm). Treatment: mild-moderate — oral vancomycin 125 mg QDS × 10 days; severe — oral vancomycin 500 mg QDS ± IV metronidazole; recurrent/refractory — fidaxomicin, faecal microbiota transplantation (FMT).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','medium','flashcard','What organisms are typically responsible for food poisoning with short incubation periods (<6 hours) versus longer incubation periods (>24 hours)?','["Short incubation (<6 hours): preformed toxin in food — Staphylococcus aureus (toxin in cream/pastry — vomiting-predominant), Bacillus cereus emetic form (fried rice). Medium incubation (6-24 hours): toxin production in gut — Clostridium perfringens (meat dishes), Bacillus cereus diarrhoeal form, ETEC. Long incubation (>24 hours): invasive bacteria — Salmonella (non-typhi, 6-72h), Shigella, Campylobacter (poultry, 1-10 days), E. coli O157:H7 (3-8 days), Listeria (up to 70 days)."]','A','EHEC (E. coli O157:H7) causes haemorrhagic colitis and haemolytic uraemic syndrome (HUS) — avoid antibiotics as they increase risk of HUS by triggering toxin release. Campylobacter is the most common bacterial cause of food poisoning in high-income countries (from undercooked poultry).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Diarrhoea & Gastroenteritis','hard','flashcard','What is haemolytic uraemic syndrome (HUS) and which organism most commonly causes it?','["HUS is a thrombotic microangiopathy characterised by the triad: (1) Microangiopathic haemolytic anaemia (MAHA — Coombs-negative haemolysis, fragmented RBCs/schistocytes); (2) Thrombocytopenia; (3) Acute kidney injury. Most common cause: Shiga toxin-producing E. coli (STEC), especially O157:H7 — following bloody diarrhoeal illness. Other causes: Shigella dysenteriae type 1, pneumococcal infection, atypical HUS (complement dysregulation)."]','A','HUS is the most common cause of acute renal failure in children in the UK. Management: supportive (dialysis for renal failure, blood transfusion); avoid antibiotics in STEC-HUS (increases Shiga toxin release and HUS risk); eculizumab (complement inhibitor) for atypical HUS. Mortality: 3-5% (mainly from CNS involvement).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','medium','flashcard','What are the Rome IV diagnostic criteria for irritable bowel syndrome (IBS)?','["Rome IV criteria for IBS: Recurrent abdominal pain at least 1 day per week over the past 3 months (with symptoms present for at least 6 months), associated with 2 or more of: (1) related to defaecation; (2) associated with a change in frequency of stool; (3) associated with a change in form (appearance) of stool. Subtypes: IBS-C (constipation-predominant), IBS-D (diarrhoea-predominant), IBS-M (mixed), IBS-U (unsubtyped)."]','A','IBS is a functional GI disorder with no structural abnormality. Pathophysiology involves visceral hypersensitivity, abnormal gut motility, gut-brain axis dysregulation, altered gut microbiome, and psychological factors. Normal bloods and colonoscopy (excluding organic disease) are required for diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','easy','flashcard','What is the diagnostic investigation of choice for confirming coeliac disease?','["(1) Serological screening: IgA anti-tissue transglutaminase (anti-TTG IgA) — highly sensitive (~95%) and specific (~98%); check total IgA simultaneously to exclude IgA deficiency (which causes false-negative TTG-IgA — use anti-TTG IgG or anti-DGP IgG if IgA deficient); (2) Confirmatory: duodenal biopsy (x4-6 biopsies from D2, x2 from the duodenal bulb) showing villous atrophy with crypt hyperplasia and intraepithelial lymphocytosis (Marsh ≥2 classification)."]','A','The patient must be on a GLUTEN-CONTAINING DIET for at least 6 weeks before serological testing and biopsy (otherwise results may be false-negative). Gluten-free diet is then commenced lifelong after confirmed diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','hard','flashcard','What are the long-term complications of untreated coeliac disease?','["(1) Nutritional deficiencies: iron, folate, vitamin B12, vitamin D (osteoporosis — increased fracture risk), zinc; (2) Refractory coeliac disease (RCD) — symptoms persist despite strict GFD; (3) Enteropathy-associated T-cell lymphoma (EATL) — rare but serious complication (10-fold increased risk); (4) Small bowel adenocarcinoma; (5) Splenic atrophy (encapsulated organism sepsis risk — pneumococcal/meningococcal vaccines recommended); (6) Dermatitis herpetiformis; (7) Peripheral neuropathy and ataxia (gluten ataxia)."]','A','Long-term strict adherence to a gluten-free diet reduces all these complications significantly. Anti-TTG IgA normalises with dietary adherence and can be used to monitor compliance. Patients with RCD type II (clonal intraepithelial lymphocytes) have high risk of EATL and require specialist management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','medium','flashcard','What is the mechanism and treatment of Giardia lamblia infection?','["Giardia lamblia (intestinalis/duodenalis) — flagellated protozoan transmitted faeco-orally (contaminated water, person-to-person). Mechanism: trophozoites attach to small bowel mucosa (duodenum/jejunum) by ventral disc, causing villous flattening and malabsorption without mucosal invasion or bloody diarrhoea. Symptoms: watery, foul-smelling, greasy diarrhoea; bloating; flatulence; abdominal cramps; weight loss; can cause chronic diarrhoea and lactase deficiency. Treatment: metronidazole 400-500 mg TDS × 5-7 days; or tinidazole 2 g single dose (higher cure rate)."]','A','Diagnosis: stool microscopy (cysts — oval, 4 nuclei; or trophozoites — pear-shaped with 2 nuclei and flagella); stool antigen ELISA (more sensitive); duodenal biopsy (gold standard for diagnosis in suspected cases with negative stool tests). Risk groups: travellers, campers, childcare workers, MSM, immunocompromised.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','easy','flashcard','What is the low-FODMAP diet and how does it help in IBS?','["Low-FODMAP diet restricts Fermentable Oligosaccharides (fructans, galacto-oligosaccharides — in wheat, rye, onions, garlic), Disaccharides (lactose — in milk, yoghurt), Monosaccharides (excess fructose — in apples, honey), And Polyols (sorbitol, mannitol — in stone fruits, artificial sweeteners). Mechanism: reduces fermentation of poorly absorbed carbohydrates by colonic bacteria, decreasing hydrogen/methane gas production, bloating, and osmotic diarrhoea. Effective in ~50-70% of IBS patients."]','A','Low-FODMAP should be implemented with a dietitian: 6-8 weeks of strict restriction phase, then gradual reintroduction of individual FODMAPs to identify personal triggers. Long-term avoidance of all FODMAPs is not recommended as it may reduce gut microbiome diversity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','hard','flashcard','What is Whipple''''s disease and how is it treated?','["Whipple''''s disease is a rare systemic infection caused by Tropheryma whipplei (gram-positive actinomycete). Classic tetrad: (1) Diarrhoea/malabsorption (steatorrhoea, weight loss); (2) Arthralgia/arthritis (often precedes GI symptoms by years — migratory, non-deforming); (3) Weight loss; (4) Fever. CNS involvement (20-40%): oculomasticatory myorhythmia (pathognomonic), cognitive decline, supranuclear ophthalmoplegia. Diagnosis: small bowel biopsy showing PAS-positive foamy macrophages in lamina propria; PCR for T. whipplei."]','A','Treatment: ceftriaxone 2 g IV daily × 2 weeks (induction), then co-trimoxazole (trimethoprim-sulfamethoxazole) 960 mg BD for 1 year (maintenance). Relapse occurs in ~30% if treatment is inadequate. CNS disease requires longer treatment and regular CSF PCR monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','medium','flashcard','What is tropical sprue and how does it differ from coeliac disease?','["Tropical sprue: malabsorption syndrome of unknown aetiology (possibly infectious) occurring in tropical regions (South and Southeast Asia, Caribbean, parts of sub-Saharan Africa). Features: chronic diarrhoea, steatorrhoea, weight loss, folate and vitamin B12 deficiency (megaloblastic anaemia). Biopsy: partial villous atrophy (less severe than coeliac). KEY DIFFERENCE from coeliac: anti-TTG IgA is NEGATIVE in tropical sprue; tropical sprue responds to folic acid + tetracycline (not gluten-free diet); occurs in people who have lived in/travelled to tropics."]','A','Treatment: folic acid 5 mg/day + tetracycline 250 mg QDS × 3-6 months. Most patients fully recover with treatment. Coeliac disease requires lifelong gluten-free diet; tropical sprue does not.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','hard','flashcard','What is small intestinal bacterial overgrowth (SIBO) and how is it diagnosed?','["SIBO is defined as ≥10⁵ colony forming units of bacteria per mL of proximal small bowel aspirate. Causes: reduced gastric acid (PPIs, gastrectomy), impaired motility (diabetes, systemic sclerosis), structural abnormalities (blind loops, strictures, jejunal diverticulosis), impaired immunity. Symptoms: bloating, flatulence, diarrhoea, steatorrhoea, vitamin B12 deficiency (bacteria consume cobalamin), fat-soluble vitamin deficiencies. Diagnosis: glucose or lactulose hydrogen breath test (early peak of hydrogen); gold standard = quantitative culture of jejunal aspirate."]','A','Treatment: rifaximin 550 mg TDS × 14 days (non-absorbable antibiotic, minimal systemic side effects). Alternatives: rotating courses of metronidazole, tetracycline, ciprofloxacin. Address underlying cause where possible. Vitamin B12 supplementation needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','medium','flashcard','What nutritional deficiencies are classically associated with malabsorption syndromes?','["Iron: microcytic anaemia, koilonychia; Folate: macrocytic anaemia, glossitis, neural tube defects in pregnancy; Vitamin B12: macrocytic anaemia, subacute combined degeneration of the cord (SACD), peripheral neuropathy; Vitamin D/Calcium: osteomalacia (adults), rickets (children), tetany, hypocalcaemia; Vitamin K: prolonged prothrombin time, bleeding; Vitamin A: night blindness, xerophthalmia; Zinc: dermatitis, hypogonadism; Vitamin E: ataxia, myopathy."]','A','Different malabsorption conditions cause specific patterns: coeliac (iron, folate, B12, calcium/D); chronic pancreatitis (fat-soluble vitamins A, D, E, K); tropical sprue (folate, B12); ileal disease/resection (B12, bile acids causing fat malabsorption); SIBO (B12 deficiency, folate may be normal or elevated as bacteria produce folate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Chronic Diarrhoea & Malabsorption','easy','flashcard','What test is used to diagnose exocrine pancreatic insufficiency and what result confirms it?','["Faecal elastase-1 (FE-1) test: measures elastase-1 (a pancreatic exocrine enzyme) in a random stool sample. Results: >200 µg/g = normal; 100-200 µg/g = moderate exocrine insufficiency; <100 µg/g = severe exocrine insufficiency. Advantages: non-invasive, not affected by pancreatic enzyme supplements, simple stool collection. Useful for confirming exocrine pancreatic insufficiency (EPI) in chronic pancreatitis."]','A','Treatment of EPI: pancreatic enzyme replacement therapy (PERT) — e.g., Creon (pancrelipase) 25,000-50,000 units per meal. If PERT response is inadequate despite adequate dosing, add a PPI (reduces gastric acid that inactivates enzymes before they reach the duodenum). Fat-soluble vitamin supplementation (A, D, E, K).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','easy','flashcard','Classify jaundice into pre-hepatic, hepatic, and post-hepatic types with key distinguishing features for each.','["Pre-hepatic (haemolytic): unconjugated bilirubin raised, urine normal colour (no bilirubinuria), urobilinogen in urine raised, normal LFTs, anaemia + reticulocytosis. Hepatic (hepatocellular): both conjugated and unconjugated bilirubin raised, dark urine, elevated ALT/AST >> ALP. Post-hepatic (obstructive): conjugated bilirubin raised, dark urine, pale stools, pruritus (bile salts in skin), elevated ALP/GGT >> ALT, dilated bile ducts on USS."]','A','Conjugated bilirubin is water-soluble and excreted in urine (darkens urine). Unconjugated bilirubin is water-insoluble and cannot be excreted by the kidney (no bilirubinuria). This is the key biochemical test to localise the cause of jaundice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','medium','flashcard','What are the liver function test (LFT) patterns in hepatocellular disease versus cholestatic disease?','["Hepatocellular pattern: markedly elevated ALT (alanine aminotransferase) and AST (aspartate aminotransferase) — often >10 times normal — with relatively mildly elevated ALP. ALT/ALP ratio >1.5. Causes: viral hepatitis, paracetamol/drug hepatotoxicity, ischaemic hepatitis, autoimmune hepatitis, Wilson''''s disease. Cholestatic pattern: markedly elevated ALP (alkaline phosphatase) and GGT — often >3 times normal — with relatively mildly elevated transaminases. ALT/ALP ratio <0.5. Causes: gallstones, cholangiocarcinoma, pancreatic head cancer, PBC, PSC, drug-induced cholestasis."]','A','ALT is more liver-specific than AST (AST is also elevated in cardiac and skeletal muscle disease). GGT elevation with ALP confirms hepatobiliary origin (vs bone disease which also raises ALP but not GGT). Isolated GGT elevation suggests alcohol use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','easy','flashcard','What is Gilbert''''s syndrome and how does it present?','["Gilbert''''s syndrome is a benign hereditary condition (autosomal recessive — reduced UGT1A1 enzyme activity) causing mild isolated unconjugated hyperbilirubinaemia (typically 20-80 µmol/L). Bilirubin rises during fasting, intercurrent illness, stress, exercise, alcohol, and menstruation. All other liver function tests (ALT, AST, ALP, albumin, PT) are completely normal. No haemolysis. Affects approximately 5% of the population."]','A','Diagnosis is clinical (young patient, episodic jaundice, otherwise normal LFTs, no haemolysis). No treatment is required. It is important to reassure patients that this is a benign, lifelong condition with no serious consequences. Gilbert''''s may cause jaundice when fasting (e.g., preoperatively).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','medium','flashcard','What investigations are used to investigate obstructive jaundice?','["First-line: abdominal ultrasound (USS) — detects dilated intra- and extrahepatic bile ducts, gallstones, pancreatic head masses. Second-line if USS non-diagnostic or incomplete: MRCP (magnetic resonance cholangiopancreatography) — non-invasive, excellent biliary and pancreatic duct visualisation without radiation or risk of pancreatitis. If therapeutic intervention needed (stone extraction, stenting): ERCP (endoscopic retrograde cholangiopancreatography). If pancreatic mass suspected: CT chest/abdomen/pelvis with contrast (staging) + EUS-FNA (tissue diagnosis)."]','A','MRCP has largely replaced diagnostic ERCP, which now has a therapeutic role. CT is the preferred staging investigation for suspected pancreatic or biliary malignancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','hard','flashcard','What are the features of Wilson''''s disease and how is it diagnosed?','["Wilson''''s disease (autosomal recessive, ATP7B mutation) — impaired copper transport causes copper accumulation in liver, brain, and eyes. Presenting features in young patients: (1) Hepatic: acute hepatitis, cirrhosis, fulminant hepatic failure (with Coombs-negative haemolytic anaemia); (2) Neuropsychiatric: tremor, dysarthria, dysphagia, psychiatric disturbance, personality change; (3) Kayser-Fleischer rings (golden-brown rings at corneal margins on slit-lamp — pathognomonic, but absent in isolated hepatic disease). Diagnosis: serum caeruloplasmin <0.2 g/L, serum copper (total), 24-hour urine copper >0.6 µmol/day, liver biopsy (copper quantification >250 µg/g dry weight)."]','A','Treatment: D-penicillamine (copper chelation — first-line) or trientine (if penicillamine intolerant). Zinc (reduces copper absorption). Liver transplantation for fulminant hepatic failure or end-stage cirrhosis (transplant corrects the metabolic defect).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','medium','flashcard','What is the difference between primary biliary cholangitis (PBC) and primary sclerosing cholangitis (PSC)?','["PBC: chronic autoimmune destruction of small intrahepatic bile ducts; predominantly affects middle-aged women (F:M = 10:1); positive anti-mitochondrial antibody (AMA-M2) in 95%; elevated ALP/GGT; symptoms: fatigue, pruritus; progresses to cirrhosis; treatment: ursodeoxycholic acid (UDCA) 13-15 mg/kg/day. PSC: fibro-inflammatory stricturing of large intra- and extrahepatic bile ducts; predominantly affects young men; associated with IBD (70-80% have UC); bead-on-a-string appearance on MRCP; elevated ALP/GGT; increased risk of cholangiocarcinoma and colorectal cancer; no effective medical therapy (liver transplant is definitive)."]','A','Both PBC and PSC cause cholestatic jaundice with elevated ALP/GGT. AMA distinguishes PBC (AMA-positive) from PSC (AMA-negative, pANCA may be positive). PSC with UC carries particularly high risk of colorectal cancer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','easy','flashcard','What is the significance of raised serum AFP (alpha-fetoprotein) in a patient with liver cirrhosis?','["AFP (alpha-fetoprotein) >200 ng/mL in a cirrhotic patient with a liver nodule >1 cm on imaging is diagnostic of hepatocellular carcinoma (HCC) — no biopsy required. AFP is used for surveillance (USS + AFP every 6 months in cirrhotic patients) and monitoring treatment response. However, AFP may be normal in 20-40% of HCC, so USS remains essential for surveillance."]','A','HCC is the most common primary liver malignancy worldwide, predominantly arising in cirrhotic livers (hepatitis B, hepatitis C, alcohol, NASH). Early HCC can be treated with radiofrequency ablation, liver resection, or transplantation (Milan criteria). Advanced HCC: sorafenib (multi-kinase inhibitor) or immunotherapy (atezolizumab + bevacizumab).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','hard','flashcard','What are the causes of a raised serum ALT in a healthy asymptomatic person found incidentally?','["Common: (1) Non-alcoholic fatty liver disease (NAFLD) — most common cause in developed countries; (2) Alcohol-related liver disease; (3) Medications (statins, amiodarone, methotrexate, herbal supplements); (4) Hepatitis B or C (viral hepatitis — may be asymptomatic). Less common: (5) Autoimmune hepatitis (may present with asymptomatic LFT elevation, especially in young women); (6) Haemochromatosis (transferrin saturation, ferritin); (7) Wilson''''s disease (young patients); (8) Alpha-1 antitrypsin deficiency; (9) Coeliac disease (check anti-TTG IgA); (10) Thyroid disease."]','A','Investigation approach: USS abdomen, hepatitis B and C serology, autoimmune screen (ANA, ASMA, anti-LKM), ferritin/transferrin saturation, caeruloplasmin (if young patient), anti-TTG IgA, TFTs, fasting lipids and glucose (metabolic syndrome). Alcohol history is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','medium','flashcard','What is NAFLD (non-alcoholic fatty liver disease) and how is it managed?','["NAFLD is hepatic steatosis (fat accumulation in >5% of hepatocytes) in the absence of significant alcohol consumption (<14 units/week for women, <21 units/week for men), viral hepatitis, or other causes. Spectrum: (1) Simple steatosis (NAFL) — benign, low progression risk; (2) Non-alcoholic steatohepatitis (NASH) — steatosis + inflammation + hepatocyte ballooning ± fibrosis — can progress to cirrhosis and HCC. Risk factors: obesity, type 2 diabetes, metabolic syndrome, dyslipidaemia."]','A','Management: (1) Weight loss 5-10% (most effective intervention — reduces steatosis and NASH); (2) Treat metabolic comorbidities (glycaemic control, statin therapy for dyslipidaemia); (3) Avoid alcohol; (4) NASH with fibrosis: vitamin E (in non-diabetics), obeticholic acid (FXR agonist — licensed); (5) Liver transplant for end-stage NAFLD cirrhosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Jaundice & Liver Disease','hard','flashcard','What are the main causes of acute hepatitis (elevated transaminases) in sub-Saharan Africa?','["(1) Hepatitis B virus (HBV) — most common cause of acute and chronic hepatitis in sub-Saharan Africa; (2) Hepatitis A virus (HAV) — faeco-oral transmission, self-limiting, more common in areas with poor sanitation; (3) Hepatitis E virus (HEV) — faeco-oral, particularly dangerous in pregnancy (mortality 20-25%); (4) Yellow fever — acute haemorrhagic fever with hepatitis; (5) Drug/herbal remedy hepatotoxicity (including traditional herbal medicines, anti-TB drugs — isoniazid, rifampicin); (6) Malaria — can cause elevated bilirubin (haemolysis) and transaminases; (7) Typhoid fever — mild hepatitis."]','A','Hepatitis B vaccination (3-dose schedule, or 4-dose if perinatal exposure) is part of the Ghana EPI. Hepatitis A vaccination is recommended for travellers. HBV is the leading cause of cirrhosis and hepatocellular carcinoma in sub-Saharan Africa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','easy','flashcard','What is the SAAG (serum-ascites albumin gradient) and how is it used to classify ascites?','["SAAG = serum albumin - ascitic fluid albumin. SAAG ≥1.1 g/dL indicates portal hypertension (transudate) — causes: cirrhosis, cardiac failure, Budd-Chiari syndrome, portal vein thrombosis. SAAG <1.1 g/dL indicates non-portal hypertension (exudate) — causes: malignancy (peritoneal carcinomatosis), infection (TB peritonitis), pancreatitis, nephrotic syndrome."]','A','SAAG has replaced the old transudate/exudate classification based on protein alone, as it is more accurate for identifying portal hypertension. Ascitic protein <25 g/L also supports cirrhotic ascites (Portal hypertension). Ascitic LDH, glucose, amylase, and cytology help with further classification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','medium','flashcard','What is spontaneous bacterial peritonitis (SBP), how is it diagnosed, and what is the treatment?','["SBP is infection of ascitic fluid without an obvious surgically treatable intra-abdominal cause. Diagnosis: ascitic fluid neutrophil (PMN) count ≥250 cells/mm³ — even if culture negative (culture-negative SBP). Common organisms: gram-negatives (E. coli, Klebsiella), gram-positives (Streptococcus pneumoniae). Treatment: IV cefotaxime 2 g TDS × 5 days (or ciprofloxacin IV/oral); IV albumin 1.5 g/kg on day 1 and 1 g/kg on day 3 (reduces HRS risk and mortality). Secondary prophylaxis: norfloxacin 400 mg/day or ciprofloxacin 500 mg/day."]','A','Indications for diagnostic paracentesis in cirrhotic ascites: new-onset ascites, hospitalisation for any reason in a cirrhotic patient, clinical deterioration (fever, abdominal pain, encephalopathy, AKI). Early diagnosis and treatment of SBP is critical — mortality is 20-40% without treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','medium','flashcard','What are the primary and secondary prophylaxis strategies for variceal haemorrhage?','["Primary prophylaxis (first bleed prevention): non-selective beta-blockers (propranolol or carvedilol — reduce cardiac output and splanchnic vasoconstriction) OR endoscopic variceal band ligation (EVL) — equally effective; indicated for medium/large varices. Secondary prophylaxis (prevention of re-bleeding): combination of non-selective beta-blocker + EVL (every 2-4 weeks until varices obliterated); TIPS for those who fail combination therapy."]','A','Propranolol: target resting HR 55-60 bpm. Carvedilol (non-selective beta-blocker + vasodilator) may be more effective than propranolol. Beta-blockers reduce portal pressure by decreasing cardiac output (β1) and splanchnic vasoconstriction (β2). They also reduce the risk of SBP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','easy','flashcard','What are the precipitants of hepatic encephalopathy in cirrhosis?','["Common precipitants (mnemonic: BAIT DOGS): Bleeding (GI haemorrhage — most common), Alkalosis (hypokalaemia), Infection (especially SBP), Toxins/drugs (sedatives, opioids, benzodiazepines), Dehydration, Over-diuresis, Gastroenteritis/diarrhoea, Surgery. Also: constipation (reduces gut transit, increases NH3 absorption), dietary protein excess (rarely a cause now), renal failure (reduced NH3 excretion), portosystemic shunts (bypass of liver)."]','A','Treatment of HE: (1) Identify and treat precipitant; (2) Lactulose (10-30 mL TDS) targeting 2-3 soft stools/day — acidifies colon, trapping NH4+ and reducing NH3 absorption; (3) Rifaximin 550 mg BD — reduces gut ammonia-producing bacteria; (4) Adequate nutrition (1.2-1.5 g protein/kg/day — do NOT restrict protein).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','hard','flashcard','What is hepatorenal syndrome (HRS) and how does it differ from other causes of AKI in cirrhosis?','["HRS is functional renal failure in advanced cirrhosis: profound splanchnic vasodilation → reduced effective arterial blood volume → renal vasoconstriction and reduced GFR. Diagnosis criteria: cirrhosis + ascites; creatinine >133 µmol/L (or doubling to >226 µmol/L within 2 weeks for HRS-1); no improvement after 2 days of albumin challenge (1 g/kg/day) and diuretic withdrawal; absence of shock; no nephrotoxins; no intrinsic renal disease (urine protein <500 mg/day, urine RBC <50/HPF). Type 1 HRS: rapidly progressive (weeks); Type 2 HRS: slow progression (months)."]','A','HRS differs from: (1) Pre-renal AKI — responds to albumin challenge; (2) ATN — urine sodium >20 mmol/L (urine Na <10 in HRS), granular casts on microscopy; (3) Glomerulonephritis — proteinuria, haematuria, renal biopsy changes. Treatment: terlipressin + albumin; definitive: liver transplantation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','medium','flashcard','How is refractory ascites managed in cirrhosis?','["Refractory ascites: ascites not controlled despite sodium restriction + maximum tolerated diuretic doses (spironolactone 400 mg + furosemide 160 mg/day) OR development of diuretic-related complications. Management: (1) Large-volume paracentesis (LVP) with albumin replacement (8 g/L ascites removed) — symptomatic relief but ascites recurs; (2) Transjugular intrahepatic portosystemic shunt (TIPS) — reduces portal pressure, controls ascites in 75-80%, reduces paracentesis frequency; risk of HE; (3) Liver transplantation — definitive treatment; (4) Indwelling peritoneal catheter — palliative option for end-stage disease."]','A','Contraindications to TIPS for ascites: hepatic encephalopathy (increases risk), heart failure, severe pulmonary hypertension, liver failure (bilirubin >85 µmol/L), polycystic liver disease. Median survival after development of refractory ascites: ~6 months — consider transplant referral.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','easy','flashcard','What is the role of beta-blockers in the management of complications of cirrhosis?','["Non-selective beta-blockers (propranolol, carvedilol, nadolol) reduce portal hypertension by: (1) β1 blockade — reduces cardiac output; (2) β2 blockade — allows α-mediated splanchnic vasoconstriction, reducing splanchnic blood flow. Indications: (1) Primary prophylaxis of variceal haemorrhage (medium/large varices or HVPG ≥10 mmHg); (2) Secondary prophylaxis of variceal haemorrhage (combined with EVL); (3) May reduce risk of SBP and HRS."]','A','Carvedilol is increasingly preferred over propranolol for primary prophylaxis as it has greater portal pressure-reducing effects. Contraindications: severe asthma, peripheral vascular disease, AV block, hypotension. Beta-blockers may be harmful in patients with refractory ascites (reduces BP and cardiac output in haemodynamically compromised patients — individualize use).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','hard','flashcard','What are the components of the Child-Pugh and MELD scoring systems for cirrhosis severity?','["Child-Pugh score (5 components, each scored 1-3): Bilirubin (µmol/L): <34=1, 34-51=2, >51=3; Albumin (g/L): >35=1, 28-35=2, <28=3; PT prolongation (seconds): <4=1, 4-6=2, >6=3; Ascites: none=1, mild=2, severe=3; Encephalopathy: none=1, grade 1-2=2, grade 3-4=3. Total: 5-6=A (well-compensated), 7-9=B (significant dysfunction), 10-15=C (decompensated). MELD score (used for transplant allocation): 9.57 × ln(creatinine) + 3.78 × ln(bilirubin) + 11.2 × ln(INR) + 6.43. Higher MELD = worse prognosis. MELD ≥15 — benefit from transplant."]','A','Child-Pugh classifies into A (compensated), B (significant dysfunction), and C (decompensated). MELD is used for organ allocation in the UK (UKELD), US, and most countries. The MELD-Na adds serum sodium to improve predictive accuracy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','medium','flashcard','What is the appropriate dietary advice for a patient with cirrhosis and ascites?','["(1) Sodium restriction: 88 mmol/day (2 g/day, or 5 g salt/day) — avoids adding salt during cooking or at table, avoids processed/tinned foods; (2) Adequate protein intake: 1.2-1.5 g/kg/day (do NOT restrict protein — malnutrition is common in cirrhosis and protein restriction worsens outcomes); (3) Small, frequent meals (5-6/day) — reduces risk of hypoglycaemia and improves nitrogen balance; (4) Late-evening snack (30-50 g carbohydrate) — prevents overnight starvation and muscle catabolism; (5) Fluid restriction only if serum sodium <125 mmol/L."]','A','Protein restriction in HE is a common misconception — protein restriction worsens sarcopenia and malnutrition without meaningfully reducing ammonia levels in most patients. Branched-chain amino acids (BCAAs) may benefit patients with muscle cramps or hepatic encephalopathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Liver Cirrhosis - Complications','hard','flashcard','What are the indications for liver transplantation in cirrhosis?','["Indications for liver transplantation: (1) Decompensated cirrhosis with MELD ≥15 or UKELD ≥49; (2) Hepatocellular carcinoma within Milan criteria (solitary tumour ≤5 cm, or ≤3 tumours each ≤3 cm, no vascular invasion, no extrahepatic disease); (3) Recurrent variceal bleeding not controlled by TIPS; (4) Refractory ascites; (5) Hepatic encephalopathy refractory to treatment; (6) Hepatorenal syndrome (terlipressin + albumin as bridge); (7) Acute liver failure (King''''s College Criteria). Contraindications: active alcohol/substance use, extrahepatic malignancy, severe cardiopulmonary disease, uncontrolled HIV, sepsis."]','A','Five-year survival after liver transplantation: approximately 70-75%. The main causes of death post-transplant: infection (immunosuppression), recurrent disease (HCV-related cirrhosis — now mitigated by DAAs; NASH), cardiovascular disease, and de novo malignancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','easy','flashcard','Define acute liver failure and name its three cardinal features.','["Acute liver failure (ALF) is the development of: (1) Jaundice; (2) Coagulopathy (INR ≥1.5); (3) Hepatic encephalopathy — within 26 weeks in a patient with NO pre-existing liver disease. Classified by time from jaundice to encephalopathy: hyperacute (<7 days — paracetamol, hepatitis A/E), acute (7-28 days), subacute (4-26 weeks — drug reactions, indeterminate — worst prognosis without transplant)."]','A','Distinguishing from decompensated cirrhosis: ALF occurs without pre-existing liver disease; the liver may be normal size (not cirrhotic). Key difference: in cirrhosis the liver is usually small and nodular; in ALF the liver may be large or normal, and disease has developed rapidly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','medium','flashcard','What are the causes of acute liver failure in (a) the UK and (b) sub-Saharan Africa/South Asia?','["UK/high-income countries: (1) Paracetamol (acetaminophen) overdose — most common (60-70%); (2) Idiosyncratic drug reactions (anti-TB drugs, NSAIDs, antibiotics, herbal remedies); (3) Viral hepatitis (A, B, E); (4) Autoimmune hepatitis; (5) Wilson''''s disease (young patients); (6) Ischaemic hepatitis (shock liver); (7) Budd-Chiari syndrome. Sub-Saharan Africa/South/Southeast Asia: (1) Viral hepatitis B (most common); (2) Hepatitis E (especially in pregnancy — 20-25% mortality); (3) Hepatitis A; (4) Traditional herbal medicine toxicity."]','A','In the UK, paracetamol accounts for >50% of all liver transplant assessments for ALF. In West Africa, hepatitis B and E are the predominant causes. Yellow fever can also cause ALF in endemic areas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','easy','flashcard','What is N-acetylcysteine (NAC) and how does it work in paracetamol overdose?','["N-acetylcysteine (NAC) is the specific antidote for paracetamol hepatotoxicity. Mechanism: paracetamol is metabolised by CYP450 to NAPQI (N-acetyl-para-benzoquinone imine), a toxic reactive metabolite that depletes hepatic glutathione. NAC replenishes glutathione stores, allowing conjugation and detoxification of NAPQI. Most effective within 8 hours of ingestion (prevents liver damage). Should still be given even in late presentations (>8-24 hours) as it improves transplant-free survival in established ALF."]','A','IV NAC regimen: 150 mg/kg in 200 mL 5% dextrose over 1 hour, then 50 mg/kg over 4 hours, then 100 mg/kg over 16 hours. Continue until liver enzymes normalise or transplant. Paracetamol nomogram (Rumack-Matthew) guides treatment decision (150 mg/kg/L at 4 hours is treatment threshold in standard-risk patients).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','medium','flashcard','What are the King''''s College Criteria for listing a patient with paracetamol-induced acute liver failure for liver transplantation?','["King''''s College Criteria for PARACETAMOL-induced ALF (meet EITHER criterion): Criterion 1 (single): Arterial pH <7.3 (after adequate fluid resuscitation, and >24 hours from ingestion). Criterion 2 (all three): Prothrombin time >100 seconds (INR >6.5) AND serum creatinine >300 µmol/L AND grade 3-4 hepatic encephalopathy — all occurring within 24 hours of each other."]','A','The KCC has a specificity of ~90% and a sensitivity of ~70% for predicting death without transplant. The arterial pH criterion is particularly important — a pH <7.3 after resuscitation carries a mortality of >80% without transplant. MELD, APACHE II, and SOFA scores are also used as adjuncts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','hard','flashcard','What are the King''''s College Criteria for non-paracetamol acute liver failure?','["King''''s College Criteria for NON-PARACETAMOL ALF — transplant if EITHER: (A) PT >100 seconds (INR >6.5) — regardless of encephalopathy grade; OR (B) Any THREE of the following five adverse criteria: (1) Age <10 years or >40 years; (2) Aetiology: drug reaction (non-paracetamol), Wilson''''s disease, or seronegative (indeterminate) — NOT hepatitis A or B; (3) Duration of jaundice to encephalopathy >7 days; (4) Serum bilirubin >300 µmol/L; (5) PT >50 seconds."]','A','Non-paracetamol ALF has a worse prognosis than paracetamol ALF without transplant. Seronegative hepatitis (indeterminate aetiology) has particularly poor outcomes. The KCC has lower sensitivity for non-paracetamol ALF (approximately 60%), so other scoring systems (APACHE II, MELD, SOFA) are used as adjuncts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','medium','flashcard','What is cerebral oedema in acute liver failure and how is it managed?','["Cerebral oedema occurs in 25-35% of patients with severe/hyperacute ALF (especially paracetamol). Mechanism: ammonia and glutamine accumulate in astrocytes, causing cytotoxic oedema; vasogenic oedema also contributes. Clinical features: agitation, delirium, hypertension + bradycardia (Cushing reflex), decerebrate posturing, seizures → brain herniation and death. Management: (1) 30° head elevation; (2) IV mannitol 0.5-1 g/kg (osmotic therapy — reduces ICP acutely); (3) Hypertonic saline (10-20%) to target Na 145-155 mmol/L; (4) Avoid hypoxia, hypercapnia, fever, hypoglycaemia; (5) Intracranial pressure (ICP) monitoring in grade 3-4 encephalopathy; (6) Cooling to 34-35°C (reduces cerebral metabolic demand)."]','A','Liver transplantation is the definitive treatment for ALF-related cerebral oedema. Early listing (King''''s College Criteria) is critical — once cerebral herniation occurs, transplant may be contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','easy','flashcard','What are the key monitoring parameters in a patient with acute liver failure?','["(1) Liver function: PT/INR (best synthetic marker — check 4-hourly), LFTs (ALT/AST, bilirubin); (2) Glucose: hourly — treat hypoglycaemia with 10-50% dextrose IV; (3) Renal function: creatinine, urine output hourly — early AKI is common; (4) Neurological status: Glasgow Coma Scale (grade of HE), pupils; (5) Infection markers: WBC, CRP, blood/urine/ascites cultures; (6) Cardiovascular: BP, MAP (target >75 mmHg), vasopressors as needed; (7) Arterial blood gas: pH, PaO2, lactate; (8) Haematological: FBC, coagulation."]','A','ALF patients should be managed in intensive care. A multidisciplinary team approach (hepatology, intensive care, transplant surgery) is essential. Early contact with a liver transplant centre is critical for patients meeting poor prognosis criteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','hard','flashcard','Why should coagulopathy in acute liver failure NOT be routinely corrected with fresh frozen plasma (FFP)?','["The PT/INR in ALF is a critical DYNAMIC PROGNOSTIC MARKER: rising PT/INR indicates worsening hepatic synthetic failure and is a key component of the King''''s College Criteria and MELD score. Correcting PT/INR with FFP obscures this prognostic information and may lead to failure to recognise the need for urgent transplantation. Additionally, FFP carries risks: circulatory overload, allergic reactions, TRALI (transfusion-related acute lung injury). Therefore, FFP is only given if: (1) active bleeding; (2) invasive procedure (central line, liver biopsy) is planned; (3) PT/INR not being used for prognosis."]','A','Vitamin K 10 mg IV/day for 3 days should be given to all ALF patients (as Vit K deficiency may partially contribute). Platelet transfusion: give if platelets <50 × 10⁹/L and invasive procedure planned, or <20 × 10⁹/L with active bleeding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','medium','flashcard','What is the management approach to hypoglycaemia in acute liver failure?','["Hypoglycaemia is a life-threatening complication of ALF (impaired hepatic gluconeogenesis and glycogenolysis). Management: (1) Monitor blood glucose hourly (or more frequently if unstable); (2) Prophylactic 10% dextrose IV infusion via central or peripheral venous access (often 500 mL/hour); (3) Treat hypoglycaemia (<3.5 mmol/L) with 50 mL of 50% dextrose IV bolus; (4) Target blood glucose 4-8 mmol/L; (5) Consider parenteral nutrition if oral route not possible."]','A','Hypoglycaemia in ALF can precipitate or worsen cerebral oedema and neurological deterioration. The liver normally provides glucose to the brain during fasting; in ALF this function is lost. Central venous access allows infusion of hypertonic glucose solutions without peripheral vein damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Acute Liver Failure','hard','flashcard','What is the role of liver transplantation in acute liver failure and what are the contraindications?','["Liver transplantation (LT) is the only definitive treatment for ALF not responding to supportive care. Indications: meeting King''''s College Criteria (paracetamol or non-paracetamol ALF). Pre-transplant work-up: ABO typing, crossmatch, cardiac and pulmonary assessment, infection screen, imaging. Contraindications: (1) Severe, uncontrolled sepsis (active infection that cannot be treated peri-operatively); (2) Multi-organ failure not expected to resolve post-transplant; (3) Cerebral herniation (fixed dilated pupils, absent brainstem reflexes) — brain death precludes transplant; (4) Active malignancy; (5) Active alcohol/substance dependence (paracetamol OD in context of intentional self-harm requires psychiatric assessment)."]','A','Auxiliary partial orthotopic liver transplantation (APOLT) — where the native liver is retained — is an option in selected cases (non-paracetamol ALF with potential for native liver regeneration), allowing withdrawal of immunosuppression if the native liver recovers. Short-term survival post-LT for ALF: 70-80% at 1 year.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','easy','flashcard','What are the two most common causes of acute pancreatitis and how can they be distinguished clinically?','["Gallstones (40-50%) and alcohol (25-35%) are the most common causes. Distinguishing features: Gallstone pancreatitis: more common in women, obese, fatty food trigger, elevated ALT/ALP (biliary pattern), gallstones on USS; Alcoholic pancreatitis: more common in men, history of heavy alcohol use, recurrent episodes, may have no gallstones on USS, amylase may be lower (relative). Both: elevated serum amylase or lipase (>3x ULN), epigastric pain radiating to back, vomiting."]','A','The aetiology of pancreatitis affects management: gallstone pancreatitis requires early cholecystectomy (same admission or within 2 weeks for mild disease) and ERCP if cholangitis present. Alcoholic pancreatitis requires alcohol cessation counselling and support.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','medium','flashcard','List the Glasgow/Imrie criteria (PANCREAS mnemonic) for severity assessment of acute pancreatitis.','["PANCREAS (each criterion scored within 48 hours of admission): P — PaO2 <8 kPa; A — Age >55 years; N — Neutrophils (WBC) >15 × 10⁹/L; C — Calcium <2.0 mmol/L (serum calcium, corrected); R — Urea >16 mmol/L (raised blood urea); E — Enzymes: LDH >600 U/L; A — Albumin <32 g/L; S — Sugar (glucose) >10 mmol/L. Score ≥3 = severe acute pancreatitis (requires HDU/ICU admission, CT, close monitoring)."]','A','Glasgow/Imrie score is assessed at 48 hours (not on admission, as some values may evolve). The Ranson criteria (5 on admission + 6 at 48h) are also used in some centres. CRP >150 mg/L at 48 hours also predicts severe disease. CT severity index (Balthazar) assesses extent of pancreatic and peripancreatic inflammation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','easy','flashcard','What is the initial management of acute pancreatitis?','["Supportive care: (1) IV fluid resuscitation (Ringer''''s lactate is preferred over normal saline — reduces risk of hyperchloraemic acidosis); start 250-500 mL/hour, guided by urine output (>0.5 mL/kg/hr) and haemodynamic response; (2) Analgesia: IV morphine or pethidine (''''meperidine'''' preferred in some countries); (3) Nil by mouth initially (advance to oral feeds as tolerated — early enteral feeding via NGT is recommended in severe pancreatitis); (4) Oxygen (if PaO2 <8 kPa); (5) Monitor: vital signs, urine output, blood glucose, calcium, renal function."]','A','Routine antibiotics are NOT recommended for acute pancreatitis unless there is evidence of cholangitis or infected necrosis. Prophylactic antibiotics have not been shown to reduce mortality or complications in sterile pancreatitis in randomised controlled trials.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','medium','flashcard','When is ERCP indicated in acute pancreatitis?','["ERCP is indicated in acute gallstone pancreatitis when: (1) Co-existing acute cholangitis (Charcot''''s triad: fever, jaundice, right upper quadrant pain) — urgent ERCP within 24 hours (or 12 hours for severe cholangitis with sepsis/shock); (2) Persistent common bile duct obstruction (elevated bilirubin/ALP not resolving, confirmed CBD stone on USS/MRCP) — ERCP within 72 hours; NOT indicated for: mild uncomplicated gallstone pancreatitis that is resolving (increases risk of ERCP-induced pancreatitis and other complications)."]','A','ERCP in the setting of pancreatitis carries risks: post-ERCP pancreatitis (3-5%), cholangitis, perforation, haemorrhage, and contrast reactions. Indomethacin suppositories (100 mg PR) are given peri-procedurally to reduce the risk of post-ERCP pancreatitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','hard','flashcard','What are the local complications of severe acute pancreatitis?','["(1) Acute peripancreatic fluid collection (APFC): fluid collection in first 4 weeks without necrosis, usually resolves spontaneously; (2) Acute necrotic collection (ANC): collection with pancreatic/peripancreatic necrosis (within 4 weeks); (3) Pancreatic pseudocyst: walled-off collection of pancreatic fluid ≥4 weeks after interstitial oedematous pancreatitis; (4) Walled-off necrosis (WON): encapsulated necrotic collection ≥4 weeks after necrotising pancreatitis; (5) Infected necrosis: ANC or WON with gas on CT (pathognomonic) or positive culture from FNA — requires intervention; (6) Pseudoaneurysm (splenic artery most common) — risk of haemorrhage; (7) Splenic/portal vein thrombosis."]','A','The Atlanta classification (revised 2012) distinguishes interstitial oedematous pancreatitis (mild, recovers fully) from necrotising pancreatitis (30% of severe cases: pancreatic necrosis ± peripancreatic necrosis). Sterile necrosis can be managed conservatively; infected necrosis requires step-up intervention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','medium','flashcard','What is chronic pancreatitis and what are its characteristic clinical features?','["Chronic pancreatitis is progressive, irreversible inflammatory destruction of the pancreatic parenchyma, leading to permanent structural changes (fibrosis, calcification) and loss of exocrine and endocrine function. Most common cause: chronic alcohol use (70%). Other causes: autoimmune, hereditary (PRSS1, SPINK1, CFTR mutations), tropical pancreatitis (tropical areas), idiopathic. Clinical features: (1) Recurrent or persistent epigastric pain radiating to back (worse with eating/alcohol, relieved by leaning forward — ''''prayer position''''); (2) Steatorrhoea (pale, greasy, floating stools — exocrine insufficiency when >90% parenchyma destroyed); (3) Diabetes mellitus (endocrine insufficiency — type 3c diabetes); (4) Weight loss; (5) Pancreatic calcification on X-ray (pathognomonic)."]','A','Diagnosis: CT scan (calcification, ductal dilatation); EUS (best sensitivity for early chronic pancreatitis); MRCP (ductal changes — ''''chain of lakes''''); faecal elastase-1 (exocrine insufficiency). Management: pain control, PERT, CREON, alcohol cessation, endoscopic/surgical drainage of dilated duct.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','easy','flashcard','What is the role of pancreatic enzyme replacement therapy (PERT) in chronic pancreatitis?','["PERT (e.g., Creon/pancrelipase) replaces the digestive enzymes that the diseased pancreas can no longer produce. Indicated for exocrine pancreatic insufficiency (steatorrhoea, weight loss, low faecal elastase-1). Administration: taken WITH meals and snacks (not before or after). Starting dose: 25,000-50,000 lipase units per meal, 10,000-25,000 per snack. Titrated to response (reduction in stool fat, weight gain). Enteric coating protects enzymes from gastric acid."]','A','If response to PERT is inadequate despite dose escalation, add a PPI (reduces gastric acid environment that can inactivate lipase even within enteric-coated granules). Fat-soluble vitamins (A, D, E, K) should be supplemented in exocrine insufficiency. Strict alcohol abstinence reduces pain and slows disease progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','hard','flashcard','What is autoimmune pancreatitis (AIP) and how does it differ from pancreatic adenocarcinoma?','["Autoimmune pancreatitis (AIP) type 1 (IgG4-related disease): affects middle-aged to older men; presents with obstructive jaundice, weight loss, and a pancreatic mass that can mimic pancreatic adenocarcinoma. Distinguishing features of AIP: elevated serum IgG4 (>135 mg/dL — in type 1); diffusely enlarged ''''sausage-shaped'''' pancreas on CT (vs focal mass in cancer); ''''halo sign'''' (peri-pancreatic low-density rim); other organ involvement (bile ducts, kidneys, lungs); dramatic response to steroid therapy (prednisolone 40 mg/day × 4 weeks — can be used as diagnostic test). Pancreatic cancer: CA 19-9 markedly elevated (AIP may have mildly elevated CA 19-9); FNA/EUS biopsy required if diagnosis uncertain."]','A','Type 2 AIP (idiopathic duct-centric pancreatitis) is associated with IBD (especially UC), is IgG4-negative, affects younger patients, and also responds to steroids. Both types of AIP respond to steroid treatment — avoiding unnecessary pancreatic surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','medium','flashcard','A 35-year-old woman develops a pancreatic pseudocyst 5 weeks after acute gallstone pancreatitis. It measures 8 cm and she has persistent abdominal pain and early satiety. What is the management?','["Symptomatic pancreatic pseudocyst ≥4 weeks old (mature wall) with persistent symptoms: drainage is indicated. Preferred approach: endoscopic ultrasound (EUS)-guided cystogastrostomy (endoscopic transgastric drainage) — creates a communication between the pseudocyst and stomach/duodenum, allowing drainage. Alternative: CT-guided percutaneous drainage (risk of external pancreatic fistula). Surgical cystojejunostomy: used if endoscopic approach fails or for complex anatomy. Asymptomatic pseudocysts: conservative management (watchful waiting) as most <6 cm resolve spontaneously."]','A','Prerequisites for endoscopic drainage: the pseudocyst must be adherent to the stomach or duodenum wall (≤1 cm between cyst and GI wall on EUS). Presence of blood vessels between cyst and GI wall (shown by EUS Doppler) is a contraindication to direct endoscopic drainage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Pancreatitis','hard','flashcard','What are the Ranson criteria for severity assessment of acute pancreatitis?','["Ranson criteria: 5 criteria on ADMISSION + 6 at 48 HOURS. On admission (GALLO): Glucose >11 mmol/L; Age >55 years; LDH >350 IU/L; AST >250 IU/L; WBC (white cells) >16 × 10⁹/L. At 48 hours (CHOBBS): Calcium <2 mmol/L; Haematocrit fall >10%; Base deficit >4 mEq/L; BUN (urea) rise >1.8 mmol/L; Blood (sequestration of fluid) >6 L; pO2 <8 kPa. Score: 0-2 = mild; 3-5 = moderate-severe; >5 = very severe (mortality >50%)."]','A','Ranson criteria are assessed over 48 hours on admission (not at re-admission or after 48h). Unlike Glasgow criteria (PANCREAS), Ranson criteria include hepatic markers (AST) and haematocrit fall. Both predict severity at 48 hours and identify patients who need close monitoring in HDU/ICU.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','easy','flashcard','What are the red flag (alarm) symptoms for colorectal cancer?','["Red flag symptoms requiring urgent investigation: (1) Rectal bleeding + change in bowel habit to looser stools/increased frequency for >6 weeks in patients >40 years; (2) Unexplained iron-deficiency anaemia; (3) Palpable rectal or right-sided abdominal mass; (4) Change in bowel habit without rectal bleeding in patients >60 years (looser stools and/or increased frequency for >6 weeks); (5) Unexplained weight loss with any change in bowel habit; (6) Positive faecal immunochemical test (FIT) in symptomatic patients."]','A','Red flag symptoms require urgent two-week wait (2WW) referral for colonoscopy in most healthcare systems. Most patients with these symptoms will NOT have cancer (positive predictive value of red flag symptoms is approximately 5-10%), but early diagnosis significantly improves survival.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','medium','flashcard','Describe the TNM and Dukes staging systems for colorectal cancer.','["TNM: T (primary tumour): T1 = submucosa, T2 = muscularis propria, T3 = through muscularis propria into pericolorectal tissues, T4a = penetrates visceral peritoneum, T4b = invades adjacent organs; N (nodes): N0 = none, N1 = 1-3 nodes, N2 = ≥4 nodes; M: M0 = no metastasis, M1 = distant metastasis. Dukes (simplified): A = limited to bowel wall (T1-2N0M0 = Stage I); B = through bowel wall, no nodes (T3-4N0M0 = Stage II); C = lymph node involvement (any T, N1-2, M0 = Stage III); D (added later) = distant metastasis (Stage IV)."]','A','5-year survival: Stage I ~90%, Stage II ~75-80%, Stage III ~50-60%, Stage IV ~10-15%. Lymphovascular invasion, perineural invasion, and high-grade tumours are adverse prognostic features within each stage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','easy','flashcard','What is the gold standard investigation for suspected colorectal cancer and what is an alternative if it cannot be performed?','["Gold standard: colonoscopy with biopsy — allows direct visualisation of the entire colon, biopsy of suspicious lesions, tattooing, and polypectomy in the same procedure. Alternative if colonoscopy declined, failed, or contraindicated: CT colonography (virtual colonoscopy) — detects polyps ≥6 mm with high sensitivity; does not allow biopsy or polypectomy; requires bowel preparation; identifies extracolonic incidental findings. Other alternatives: flexible sigmoidoscopy (only left colon) + CT abdomen/pelvis (for right colon). Barium enema is now rarely used."]','A','Colonoscopy has a cecal intubation rate of approximately 95% in experienced hands. If cecal intubation fails, CT colonography completes the colonic evaluation. Colonoscopy carries risks: perforation (~1:1000), bleeding (~1:500), cardiopulmonary events during sedation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','hard','flashcard','What is Lynch syndrome (HNPCC) and what are its associated cancers and surveillance recommendations?','["Lynch syndrome (Hereditary Non-Polyposis Colorectal Cancer) is caused by germline mutations in mismatch repair (MMR) genes: MLH1, MSH2, MSH6, PMS2. Characteristics: early-onset colorectal cancer (<50 years), multiple synchronous/metachronous CRC, predominantly right-sided CRC (proximal colon), tumours are MMR-deficient (MSI-high). Associated extracolonic cancers: endometrial (highest risk after CRC), ovarian, gastric, urinary tract (transitional cell), small bowel, hepatobiliary, brain (Turcot syndrome variant). Surveillance: colonoscopy every 1-2 years from age 25 (or 5 years before youngest affected relative); annual endometrial biopsy from age 35-40 for women."]','A','Amsterdam II Criteria (clinical diagnosis): 3 or more relatives with Lynch-associated cancers, involving at least 2 successive generations; at least 1 diagnosed <50 years; one must be a first-degree relative of the other two. All CRC tumours should be tested for MMR protein deficiency (immunohistochemistry) as a universal screening strategy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','medium','flashcard','What is the population-based colorectal cancer screening programme in high-income countries and why is it effective?','["Most high-income countries (UK, Europe, Australia, USA) offer: Faecal Immunochemical Test (FIT) every 2 years to individuals aged 50-74 years (some expanding to 45-75). Positive FIT → diagnostic colonoscopy. Alternative: flexible sigmoidoscopy (one-off at age 55 — UK Bowel Cancer Screening Programme). Effectiveness: reduces CRC-specific mortality by 15-25% through detection of early-stage cancers (Stage I-II) and pre-malignant polyps (adenomas). Adenoma detection → polypectomy prevents progression to cancer."]','A','The FIT test detects human haemoglobin in stool with high specificity for colorectal bleeding sources. Sensitivity for CRC: approximately 79%; for advanced adenoma: 40-50%. The UK bowel cancer screening programme began in 2006 and has significantly shifted the stage distribution of CRC to earlier stages.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','medium','flashcard','What adjuvant chemotherapy is given for stage III (Dukes C) colon cancer and what is its goal?','["Stage III (lymph node positive) colon cancer is treated with adjuvant chemotherapy after curative surgical resection (colectomy) to eradicate micrometastases and reduce risk of recurrence. Standard regimens: FOLFOX (infusional 5-fluorouracil + leucovorin + oxaliplatin, every 2 weeks × 12 cycles) or CAPOX/XELOX (capecitabine + oxaliplatin, every 3 weeks × 8 cycles) — both given for approximately 6 months. Adjuvant chemotherapy reduces the risk of relapse by approximately 25-30% and improves 5-year survival by approximately 10%."]','A','Oxaliplatin''''s main side effects: peripheral neuropathy (cumulative, dose-limiting — cold-induced or persistent), nausea, thrombocytopenia. Capecitabine side effects: hand-foot syndrome, diarrhoea. Stage II CRC (high-risk features: T4, perforation, inadequate lymph node sampling, lymphovascular invasion) may also benefit from adjuvant chemotherapy — discuss at MDT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','hard','flashcard','What is the significance of RAS and BRAF mutation testing in metastatic colorectal cancer?','["RAS mutations (KRAS, NRAS): present in approximately 50% of colorectal cancers. Mutations in these genes activate the RAS/MAPK signalling pathway independently of EGFR, making EGFR-targeted therapies (cetuximab, panitumumab) INEFFECTIVE in RAS-mutant tumours. Therefore, all patients with metastatic CRC must have RAS mutation testing before considering anti-EGFR therapy — only RAS/BRAF wild-type patients benefit. BRAF mutation (V600E): present in approximately 10% of CRC, associated with poor prognosis; anti-EGFR therapy has reduced efficacy in BRAF-mutant tumours; targeted therapy: encorafenib + cetuximab for BRAF V600E metastatic CRC."]','A','MSI-high (microsatellite instability-high) / MMR-deficient tumours (approximately 15% of CRC, enriched in right-sided, early-stage tumours) respond to immunotherapy (pembrolizumab — PD-1 inhibitor) as first-line treatment for metastatic MSI-H CRC. This includes Lynch syndrome-associated tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','easy','flashcard','What are the surgical options for colorectal cancer and how does the location of the tumour affect the operation?','["Colon cancer: (1) Right hemicolectomy (caecum, ascending and proximal transverse colon); (2) Extended right hemicolectomy (to splenic flexure); (3) Left hemicolectomy (descending and sigmoid colon); (4) Sigmoid colectomy. Rectal cancer: (1) Anterior resection (high rectum — with anastomosis, sphincter-preserving); (2) Hartmann''''s procedure (sigmoid/high rectal resection + end colostomy, without anastomosis — used in emergency or frail patients); (3) Abdominoperineal resection (APR) (low rectal cancer involving sphincters — removes rectum and anal canal + permanent colostomy)."]','A','Total mesorectal excision (TME) is the standard surgical technique for rectal cancer — removes the rectum with the entire intact mesorectum (the fatty envelope containing lymph nodes and blood vessels), dramatically reducing local recurrence from ~30% to <10%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','hard','flashcard','What is the management of resectable liver metastases from colorectal cancer?','["Resectable liver-only (or liver-dominant) metastases from colorectal cancer should be considered for curative-intent treatment: (1) Surgical resection (hepatectomy) if adequate residual functional liver volume (≥20-30% of future liver remnant); 5-year survival after liver resection: approximately 30-50%; (2) Neoadjuvant chemotherapy (FOLFOX/CAPOX ± bevacizumab or anti-EGFR for RAS/BRAF wild-type) — can convert borderline-resectable to resectable disease; (3) Portal vein embolisation (PVE) — hypertrophies the future liver remnant before major hepatectomy; (4) Ablative techniques (radiofrequency or microwave ablation) for patients unfit for surgery."]','A','The EORTC intergroup trial (EPOC) showed improved progression-free survival with perioperative FOLFOX chemotherapy (before + after surgery) compared to surgery alone for resectable liver metastases. Overall, approximately 20-25% of patients with metastatic CRC are eligible for curative liver resection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed'),
('{"medicine"}','Medicine','Gastroenterology','Clinicals','Colorectal Cancer & Screening','medium','flashcard','What is familial adenomatous polyposis (FAP) and how is it managed?','["FAP is an autosomal dominant condition caused by germline mutation in the APC (adenomatous polyposis coli) gene. Characterised by: development of hundreds to thousands of colorectal adenomatous polyps by early adulthood; 100% risk of colorectal cancer by age 40 if untreated; also associated with: duodenal/ampullary polyps (duodenal cancer risk 5-10%), desmoid tumours, thyroid cancer, gastric fundic gland polyps, CHRPE (congenital hypertrophy of retinal pigment epithelium). Management: flexible sigmoidoscopy from age 13-15 (annual); prophylactic colectomy (usually age 16-25) when polyp burden becomes unmanageable — proctocolectomy + ileal pouch-anal anastomosis (IPAA) or proctocolectomy + ileostomy."]','A','Attenuated FAP (AFAP): fewer polyps (10-100), later onset (30s-40s), caused by mutations at 5'''' or 3'''' end of APC gene. MUTYH-associated polyposis (MAP): autosomal recessive, fewer polyps than classic FAP, caused by MUTYH base excision repair gene mutations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''''s Principles of Internal Medicine, 20th Ed');
